# Export the authors' released biodiesel example's DATA at a chosen noise level, generated by
# their own code (DENG-MIT/ChemKAN), plus its normalization and the initial parameters.
#
#   julia +1.11.1 --startup-file=no --project=<authors_dir> export_noisy_data.jl <authors_dir> <noise> <out_dir>
#
# Runs ChemKAN_biodiesel_example_compat.jl verbatim up to and including `u0 = u0_list[1, :];`
# (data generation with Random.seed!(1234), Lux.setup, the global min/max normalization),
# changing ONLY the line `noise = 0.00;` to the requested value. Nothing in <authors_dir> is
# written. Note: the noise draws advance the RNG before Lux.setup, so p_init depends on noise.
#
# Writes (writedlm, full precision; experiment e = 1..40 in the script's order: 1-20 noisy
# train, 21-30 noisy test, 31-40 noise-free test):
#   ode_data.txt, normdata.txt : 240 x 30, row (e-1)*6 + s = experiment e, species s
#   u0_norm.txt   : 40 x 7 normalized initial states [Y1..Y6, T]
#   all_temps.txt : 40 raw initial temperatures
#   ymin.txt, ymax.txt : 6 per-species global min/max;  T_minmax.txt : 2
#   p_init.txt    : 156 initial parameters;  tsteps.txt : 30 times;  noise.txt

using DelimitedFiles

authors, noise, out = abspath(ARGS[1]), parse(Float64, ARGS[2]), abspath(ARGS[3])
script = joinpath(authors, "ChemKAN_biodiesel_example_compat.jl")
lines = split(read(script, String), '\n')
inoise = findfirst(l -> strip(l) == "noise = 0.00;", lines)
inoise === nothing && error("noise line not found in $script")
lines[inoise] = "noise = $(noise);"
stop = findfirst(l -> strip(l) == "u0 = u0_list[1, :];", lines)
stop === nothing && error("normalization end line not found in $script")

cd(authors)
task_local_storage(:SOURCE_PATH, script) do
    include_string(Main, join(lines[1:stop], '\n'), script)
end

mkpath(out)
flat(a) = reduce(vcat, [a[e, :, :] for e in 1:size(a, 1)])    # (n_exp*6) x 30
writedlm(joinpath(out, "ode_data.txt"), flat(Main.ode_data_list))
writedlm(joinpath(out, "normdata.txt"), flat(Main.normdata))
writedlm(joinpath(out, "u0_norm.txt"), Main.u0_list)
writedlm(joinpath(out, "all_temps.txt"), Main.all_temps)
writedlm(joinpath(out, "ymin.txt"), vec(Main.ymin))
writedlm(joinpath(out, "ymax.txt"), vec(Main.ymax))
writedlm(joinpath(out, "T_minmax.txt"), [minimum(Main.all_temps), maximum(Main.all_temps)])
writedlm(joinpath(out, "p_init.txt"), Main.p)
writedlm(joinpath(out, "tsteps.txt"), collect(Main.tsteps))
writedlm(joinpath(out, "noise.txt"), [noise])
println("noise $(noise): n_exp $(size(Main.ode_data_list, 1)); wrote data, normalization, p_init to $(out)")
